 [Serializable]class LoadRow{public int count,visible,materials,meshes,textures,activeLights,poolLights,shadowLights;public long textureBytes,meshBytes;public double cpuMedianMs;}
 public static void Load(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rows=new List<LoadRow>();foreach(int n in new[]{9,225}){var root=new GameObject("共有確認 "+n);var fixtures=new List<RoomTorchInstance>();int side=n==9?3:15;for(int i=0;i<n;i++){var l=MakeLamp(new Vector3((i%side-side/2)*2,1.65f,(i/side-side/2)*2),Quaternion.identity,root.transform);fixtures.Add(l.GetComponent<RoomTorchInstance>());}var b=root.AddComponent<RoomTorchBudget>();b.Configure(fixtures.ToArray());Advance(b,Vector3.zero);Check(b.ActiveLights==2&&b.PooledLampLightCount==2,"two shadowed lamps within shared six at "+n);Check(root.GetComponentsInChildren<Light>().Count(l=>l.enabled&&l.shadows!=LightShadows.None)==2,"two shadow lights");
 var meshes=root.GetComponentsInChildren<MeshFilter>().Select(f=>f.sharedMesh).Distinct().ToArray();var materials=root.GetComponentsInChildren<Renderer>().Select(f=>f.sharedMaterial).Distinct().ToArray();var textures=materials.SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).Where(t=>t).Distinct().ToArray();Check(meshes.Length==2&&materials.Length==2&&textures.Length==4,"shared references");var c=Camera();c.transform.position=new Vector3(0,15,-12);c.transform.LookAt(Vector3.zero);var planes=GeometryUtility.CalculateFrustumPlanes(c);var rt=new RenderTexture(960,540,24);rt.Create();c.targetTexture=rt;var cpu=new List<double>();for(int i=0;i<9;i++){var sw=System.Diagnostics.Stopwatch.StartNew();c.Render();sw.Stop();if(i>=4)cpu.Add(sw.Elapsed.TotalMilliseconds);}rows.Add(new LoadRow{count=n,visible=fixtures.Count(f=>GeometryUtility.TestPlanesAABB(planes,f.GetComponent<Renderer>().bounds)),materials=materials.Length,meshes=meshes.Length,textures=textures.Length,activeLights=b.ActiveLights,poolLights=b.PooledLampLightCount,shadowLights=2,textureBytes=textures.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t)),meshBytes=meshes.Sum(m=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(m)),cpuMedianMs=cpu.OrderBy(t=>t).ElementAt(cpu.Count/2)});c.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);
 foreach(var f in fixtures)f.gameObject.SetActive(false);Advance(b,Vector3.zero);Check(b.ActiveLights==0&&root.GetComponentsInChildren<Light>().All(l=>!l.enabled),"disabled fixtures release slots");UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(c.gameObject);}
 File.WriteAllText(Path.Combine(Out,"load.json"),"{\"cases\":["+string.Join(",",rows.Select(JsonUtility.ToJson))+"],\"gpuMeasured\":false,\"meaning\":\"CPU render submission only, not total frame performance guarantee\"}");}
